import json,freya
r=json.load(open('results/a-run1.json'))
row=[x for x in r['rows'] if x['id']=='PUB-04'][0]
c=freya.get_call(row['call_id'])
for m in c['messages']:
    s=m.get('message') or ''
    if '"route_evaluated"' in s and '"from_node":"facts"' in s:
        vt=json.loads(s)['variable_table']
        for k,v in vt.items():
            if 'product' in k or k in ('acct_state','debt_line','callback_facts') or 'get_account' in k or 'api_call' in k or 'fetch' in k:
                print(k, '=>', repr(v)[:300])
EOF

python3 - <<'EOF'
import json,freya
r=json.load(open('results/a-run2.json'))
for row in r['rows']:
    if row['id'] in ('PUB-06','PUB-10'):
        print('=====',row['id'],row['failed'])
        c=freya.get_call(row['call_id'])
        for m in c.get('messages',[]):
            if m.get('role') in ('assistant','user'): print(m['role'],':',m.get('message'))
            elif 'function_call_complete' in (m.get('message') or '') and 'create_promise' in m['message']: print('   TOOL', m['message'][:250])
EOF
